const raw = $input.first().json;
const src = raw.body && typeof raw.body === 'object' ? raw.body : raw;

const brief = String(src.brief || '').trim();
if (!brief) throw new Error('brief is required');

const target = String(src.target || 'generic').trim() || 'generic';
const title = String(src.title || '').trim();
const slug = String(src.slug || '').trim();
const model = String(src.model || 'openai/gpt-4o').trim();
const status = String(src.status || 'draft').trim();

return [{
  json: {
    brief,
    target,
    title,
    slug,
    model,
    status,
    spaceId: '019fd6a5-7ed6-7ab0-ba42-d93755c420fc',
    docmostBase: 'https://docmost.tiger-bushmaster.ts.net',
    metamcpUrl: 'https://metamcp.tiger-bushmaster.ts.net/metamcp/openclaw/mcp',
    openRouterBody: {
      model,
      temperature: 0.4,
      messages: [
        {
          role: 'system',
          content: [
            'You are a specialist prompt-engineering agent.',
            'Design prompts that reliably cause another AI agent to perform the intended task.',
            '',
            'Return ONLY:',
            '1) One status line: target=<t> · slug=<slug> · v1 · status=draft',
            '2) The full executable prompt in a single markdown fenced block.',
            '',
            'Prompt sections (skip empty): Goal, Context, Requirements, Constraints, Verification, Deliverables.',
            `Target executor: ${target}.`,
            "Do not invent unrelated requirements. Goal is the work, not 'write a prompt'.",
          ].join('\n'),
        },
        { role: 'user', content: brief },
      ],
    },
  },
}];

const norm = $('Normalize').first().json;
const or = $input.first().json;
const content = or?.choices?.[0]?.message?.content || '';
if (!content) {
  throw new Error('OpenRouter returned empty content: ' + JSON.stringify(or).slice(0, 500));
}

let body = content;
const fence = content.match(/```(?:markdown)?\n([\s\S]*?)```/);
if (fence) body = fence[1].trim();

const statusLine = (content.split('\n').find((l) => /target=/.test(l)) || '');
const slugFromLine = (statusLine.match(/slug=([a-z0-9-]+)/i) || [])[1];
const targetFromLine = (statusLine.match(/target=([a-z0-9-]+)/i) || [])[1];

function kebab(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 64);
}

const slug = norm.slug || slugFromLine || kebab(norm.title) || kebab(norm.brief).slice(0, 48) || `prompt-${Date.now()}`;
const target = norm.target || targetFromLine || 'generic';
const title = norm.title || slug;
const now = new Date().toISOString();

const pageMarkdown = [
  '---',
  `slug: ${slug}`,
  `target: ${target}`,
  `status: ${norm.status || 'draft'}`,
  'version: 1',
  `model: ${norm.model}`,
  `created: ${now}`,
  `updated: ${now}`,
  `brief: ${JSON.stringify(norm.brief)}`,
  'source: n8n/prompt-generate',
  '---',
  '',
  body,
].join('\n');

return [{
  json: {
    slug,
    title,
    target,
    status: norm.status || 'draft',
    version: 1,
    model: norm.model,
    body,
    pageMarkdown,
    spaceId: norm.spaceId,
    docmostBase: norm.docmostBase,
    metamcpUrl: norm.metamcpUrl,
    mcpInitBody: {
      jsonrpc: '2.0',
      id: 1,
      method: 'initialize',
      params: {
        protocolVersion: '2024-11-05',
        capabilities: {},
        clientInfo: { name: 'n8n-prompt-generate', version: '1.0.0' },
      },
    },
    mcpCreateArgs: {
      spaceId: norm.spaceId,
      title,
      content: pageMarkdown,
      format: 'markdown',
    },
  },
}];

const fmt = $('Format Docmost Body').first().json;
const res = $input.first().json;

const headers = res.headers || res.header || {};
const lower = {};
for (const [k, v] of Object.entries(headers)) {
  lower[String(k).toLowerCase()] = Array.isArray(v) ? v[0] : v;
}
const sessionId = lower['mcp-session-id'] || lower['mcp_session_id'] || '';
if (!sessionId) {
  throw new Error('MetaMCP missing mcp-session-id. Check credential (X-API-Key) and URL /metamcp/openclaw/mcp. Response: ' + JSON.stringify(res).slice(0, 400));
}

return [{
  json: {
    ...fmt,
    mcpSessionId: sessionId,
    mcpCallBody: {
      jsonrpc: '2.0',
      id: 2,
      method: 'tools/call',
      params: {
        name: 'docmost__create_page',
        arguments: fmt.mcpCreateArgs,
      },
    },
  },
}];

const fmt = $('Extract MCP Session').first().json;
const res = $input.first().json;
const rawBody = typeof res.body === 'string' ? res.body : (res.body ? JSON.stringify(res.body) : JSON.stringify(res));

let parsed = null;
const dataMatch = String(rawBody).match(/data:\s*(\{[\s\S]*\})/);
if (dataMatch) {
  try { parsed = JSON.parse(dataMatch[1]); } catch (_) {}
}
if (!parsed) {
  try { parsed = typeof res.body === 'object' ? res.body : JSON.parse(String(rawBody)); } catch (_) {}
}

const result = parsed?.result || parsed || {};
const err = parsed?.error;
if (err) {
  throw new Error('MetaMCP tools/call error: ' + JSON.stringify(err).slice(0, 500));
}

// MCP tool results often nest text JSON in content[]
let page = result;
const texts = (result.content || []).filter((c) => c.type === 'text').map((c) => c.text);
for (const t of texts) {
  try {
    const j = JSON.parse(t);
    if (j && (j.id || j.pageId || j.slugId)) { page = j; break; }
    if (j?.structuredContent) { page = j.structuredContent; break; }
  } catch (_) {}
}
if (page.structuredContent) page = page.structuredContent;

const pageId = page.id || page.pageId || '';
const slugId = page.slugId || '';
const base = String(fmt.docmostBase || '').replace(/\/$/, '');
const url = slugId ? `${base}/s/prompts/p/${slugId}` : `${base}/s/prompts`;

return [{
  json: {
    ok: true,
    slug: fmt.slug,
    status: fmt.status,
    version: fmt.version,
    model: fmt.model,
    target: fmt.target,
    pageId,
    slugId,
    url,
    body: fmt.body,
  },
}];
